 as r(slug text, old_summary text, summary text, old_title text, title text, old_intro text, new_intro text)
)
update public.foamlab_content c
set title=r.title, summary=r.summary,
 body=case when strpos(c.body,r.old_intro)=1
           then r.new_intro || substr(c.body,length(r.old_intro)+1)
           else c.body end
from revised r
where c.slug=r.slug and c.summary=r.old_summary and c.title=r.old_title;
